struct game_control { int name; int type; void *mapping; };
struct value_type { const int first; game_control second; };
struct node { int color; node *parent; node *left; node *right; value_type value; };
struct tree { node header; unsigned int node_count; };
struct result { node *position; bool inserted; };
extern "C" node *tree_insert(tree *, node *, node *, const value_type &)
  __asm__("_M_insert__t8_Rb_tree5ZiZt4pair2ZCiZ12game_controlZt10_Select1st1Zt4pair2ZCiZ12game_controlZt4less1ZiZt12my_allocator1Z12game_controlP18_Rb_tree_node_baseT1RCt4pair2ZCiZ12game_control");
result *insert_unique(result *, tree *, const value_type &)
  __asm__("insert_unique__t8_Rb_tree5ZiZt4pair2ZCiZ12game_controlZt10_Select1st1Zt4pair2ZCiZ12game_controlZt4less1ZiZt12my_allocator1Z12game_controlRCt4pair2ZCiZ12game_control");
result *insert_unique(result *out, tree *self, const value_type &value) {
  node *y=&self->header,*x=self->header.parent; bool comp=true;
  while(x){y=x;comp=value.first<x->value.first;x=comp?x->left:x->right;}
  node *j=y;
  if(comp){
    if(j==self->header.left){out->position=tree_insert(self,x,y,value);out->inserted=true;return out;}
    if(j->left){j=j->left;while(j->right)j=j->right;}
    else{node*p=j->parent;while(j==p->left){j=p;p=p->parent;}j=p;}
  }
  if(j->value.first<value.first){out->position=tree_insert(self,x,y,value);out->inserted=true;}
  else{out->position=j;out->inserted=false;}
  return out;
}
